function materialMatches(m){if(state.institution&&m.institution!==state.institution)return false;const ids=new Set(filterRoutes(catalog,{...state,query:''}).map(r=>r.id));if(m.routeIds?.length&&!m.routeIds.some(id=>ids.has(id)))return false;if(!m.routeIds?.some(id=>ids.has(id)))return false;if(state.query&&!JSON.stringify([m.title,m.requirements,m.items,m.note,displayInstitution(m.institution)]).toLowerCase().includes(state.query.toLowerCase()))return false;return true;}
